export const newebpayField = (code:string) => newebpayFields.find(f=>f[0]===code);
export function newebpayVisible(code:string,legal?:string,kind?:string|null):boolean { const f=newebpayMeta[code]; return !!f && (f.visible.includes('ANY') || f.visible.includes(legal??'') || legal==='COMPANY' && !!kind && f.visible.includes('T'+kind)); }
